\title{A Colorful Carath\'eodory Theorem for Convex Cones}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
Carath\'eodory's theorem and its colorful refinement, due to B\'ar\'any, are
cornerstones of combinatorial convexity, concerning the representation of a point
as a convex combination of members of one or several finite sets. We develop the
analogue for \emph{convex cones}, with the origin as the distinguished target.
Replacing convex combinations (nonnegative weights summing to one) by nontrivial
conical combinations (nonnegative weights, not all zero), we prove three results.
First, a \emph{homogeneity bridge}: for the origin, conical and convex
representability are equivalent, since a conical representation rescales by its
strictly positive total weight to a convex one. Second, a sharp
\emph{one-dimensional cone colorful Carath\'eodory theorem}: given $r \ge 2$ finite
color classes of reals, each capturing the origin conically, there is a colorful
transversal, one element per class, that captures the origin; the threshold $r \ge
2$ is best possible, witnessed by $\{1,-1\}$. Third, a \emph{conic Carath\'eodory
bound}: in dimension $d$, capturing the origin conically needs at most $d+1$
vectors. The unifying phenomenon is homogeneity: the origin is the unique point at
which cone- and hull-membership coincide unconditionally, collapsing the conical
colorful problem onto the classical affine one and correcting the naive color count
$d$ to the sharp count $d+1$.
\end{abstract}

\maketitle

\section{Introduction}

Carath\'eodory's theorem (1907) states that a point in the convex hull of a set
$S \subseteq \R^d$ already lies in the convex hull of at most $d+1$ points of $S$.
B\'ar\'any's colorful generalization (1982) states that if a point lies in the
convex hull of each of $d+1$ color classes $S_0,\dots,S_d \subseteq \R^d$, then it
lies in the convex hull of a colorful selection $\{x_0,\dots,x_d\}$ with $x_i \in
S_i$. These theorems underlie the First Selection Lemma, colorful Tverberg
theorems, and centerpoint results.

A parallel object is the \emph{convex cone}, the set of nonnegative combinations of
a family of vectors, which governs homogeneous linear inequalities and conic
duality. We study the cone-theoretic analogues of Carath\'eodory's and B\'ar\'any's
theorems, with the origin --- the canonical distinguished point of a cone --- as
the target.

Throughout, $V$ is a real vector space, $p : \iota \to V$ a family of vectors
indexed by a type $\iota$, and $s$ a finite index set.

\begin{definition}[Nontrivial conical capture]
The family $p$ \emph{captures the origin conically} on $s$ if there exist weights
$w : \iota \to \R$ with $w_i \ge 0$ for all $i \in s$, some $i \in s$ with $w_i >
0$, and $\sum_{i \in s} w_i\, p_i = 0$.
\end{definition}

\begin{definition}[Convex capture]
The family $p$ \emph{captures the origin convexly} on $s$ if there exist weights
$w : \iota \to \R$ with $w_i \ge 0$ for all $i \in s$, $\sum_{i \in s} w_i = 1$, and
$\sum_{i \in s} w_i\, p_i = 0$.
\end{definition}

The strict-positivity clause in Definition~1 is essential: without it the all-zero
weight vector would make every family capture the origin vacuously, trivializing
the theory.

\section{The homogeneity bridge}

\begin{theorem}[Homogeneity bridge]\label{thm:bridge}
For every finite $s$ and family $p : \iota \to V$, the origin is a nontrivial
conical combination of $\{p_i : i \in s\}$ if and only if it is a convex
combination.
\end{theorem}

\begin{proof}
($\Rightarrow$) Let $w_i \ge 0$, not all zero, with $\sum_{i\in s} w_i p_i = 0$.
Set $S = \sum_{i \in s} w_i$. Comparing the sum to a single strictly positive term
gives $S > 0$. Put $w'_i = w_i / S$. Then $w'_i \ge 0$, $\sum_{i\in s} w'_i = 1$,
and $\sum_{i\in s} w'_i p_i = \tfrac1S \sum_{i\in s} w_i p_i = 0$.

($\Leftarrow$) If $\sum_{i\in s} w_i = 1$ then not all $w_i$ vanish, so some
nonnegative $w_i$ is strictly positive, and the same weights witness a nontrivial
conical capture.
\end{proof}

\begin{remark}
The forward rescaling moves the balance point from $0$ to $\tfrac1S\cdot 0 = 0$: it
is fixed only because the target is the origin. For any nonzero target the
equivalence fails. Homogeneity of the cone is precisely what identifies conical and
convex capture at the origin.
\end{remark}

\section{The one-dimensional colorful theorem}

We specialize to $V = \R$, $p = \mathrm{id}$, so a color class is a finite set
$s \subseteq \R$.

\begin{theorem}[Sign classification]\label{thm:sign}
A finite set $s \subseteq \R$ captures the origin conically if and only if $0 \in
s$, or $s$ contains both a strictly positive and a strictly negative element.
\end{theorem}

\begin{proof}
($\Leftarrow$) If $0 \in s$, weight $1$ on $0$ works. If $a > 0$ and $b < 0$ lie in
$s$, then $(-b)a + a b = 0$ with weights $-b, a > 0$.

($\Rightarrow$) Suppose $0 \notin s$ and $w_x \ge 0$, not all zero, with $\sum_{x
\in s} w_x x = 0$. If $s$ had no positive element, every $x \in s$ is negative, so
$\sum w_x x < 0$, a contradiction; symmetrically $s$ cannot lack a negative
element.
\end{proof}

\begin{theorem}[Cone colorful Carath\'eodory, dimension one]\label{thm:colorful}
Let $r \ge 2$ and let $C_0,\dots,C_{r-1} \subseteq \R$ be nonempty finite sets,
each capturing the origin conically. Then there is a transversal $t_i \in C_i$
whose image captures the origin conically. The threshold $r \ge 2$ is sharp.
\end{theorem}

\begin{proof}
If some $C_{i_0}$ contains $0$, set $t_{i_0} = 0$ and choose $t_i \in C_i$
arbitrarily otherwise; the image contains $0$ and captures the origin by
Theorem~\ref{thm:sign}. Otherwise, by Theorem~\ref{thm:sign} each $C_i$ straddles
the origin; since $r \ge 2$, pick a positive $t_0 \in C_0$ and a negative $t_1 \in
C_1$, and choose the rest arbitrarily. With $a = t_0 > 0$, $b = t_1 < 0$, the
weights $-b$ on coordinate $0$ and $a$ on coordinate $1$ give $(-b)a + ab = 0$, a
nontrivial conical capture.

For sharpness, the single class $\{1,-1\}$ captures the origin, but any transversal
picks one nonzero real, which cannot.
\end{proof}

\section{The conic Carath\'eodory bound}

Assume $\dim_\R V = d < \infty$.

\begin{lemma}[Affine dependence]\label{lem:aff}
If $|s| > d+1$, there exist $u : \iota \to \R$ with $\sum_{i\in s} u_i p_i = 0$,
$\sum_{i\in s} u_i = 0$, and some $u_i \ne 0$.
\end{lemma}

\begin{proof}
Lift $p_i$ to $q_i = (p_i, 1) \in V \times \R$, a space of dimension $d+1$. Any
$|s| > d+1$ vectors $q_i$ are linearly dependent; a nontrivial dependence
$\sum u_i q_i = 0$ yields both coordinate equations.
\end{proof}

\begin{lemma}[Pruning]\label{lem:prune}
If $p$ captures the origin convexly on $s$ and $|s| > d+1$, then it does so on some
$t \subsetneq s$.
\end{lemma}

\begin{proof}
Let $w$ be the convex witness and $u$ the affine dependence of
Lemma~\ref{lem:aff}. For $w_i(\theta) = w_i + \theta u_i$, both $\sum w_i(\theta) =
1$ and $\sum w_i(\theta) p_i = 0$ persist. Since some $u_j < 0$, set $\theta^* =
\min\{ w_j / (-u_j) : u_j < 0\}$. Then $w_i(\theta^*) \ge 0$ for all $i$ and
$w_j(\theta^*) = 0$ at the minimizer. Restrict to the support.
\end{proof}

\begin{theorem}[Conic Carath\'eodory bound]\label{thm:carath}
If $p$ captures the origin conically on $s$, then it does so on some $t \subseteq s$
with $|t| \le d+1$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:bridge}, pass to a convex capture on $s$. Apply
Lemma~\ref{lem:prune} until the support has at most $d+1$ elements; the process
terminates as the support strictly decreases. Convert back by
Theorem~\ref{thm:bridge}.
\end{proof}

\section{Applications and discussion}

Capturing the origin conically by $\{a_i\}$ is equivalent, by Gordan's theorem, to
infeasibility of the strict system $a_i^\top x > 0$; Theorem~\ref{thm:carath} says
such a certificate uses at most $d+1$ constraints, a Helly-type compactness
statement. Theorem~\ref{thm:colorful} is the origin-anchored cone instance of the
colorful paradigm: if each color block individually forces a balance, a single
representative per block still does. The organizing principle is homogeneity: the
origin is the unique point where conical and convex capture coincide
unconditionally, so the classical toolbox transports to cones verbatim, with the
color count corrected from $d$ to $d+1$.

The one-dimensional theorem and the bridge isolate the exchange step needed for the
full-dimensional colorful cone theorem, conjectured to hold with $d+1$ colors;
quantitative counting, positive-circuit sharpness, and an interior-capture variant
are natural next directions.

