function CONICAL_TO_CONVEX(w[1..n]):
    S <- sum(w[i] for i in 1..n)
    assert S > 0            # some w[i] > 0 guarantees this
    for i in 1..n:
        w'[i] <- w[i] / S
    return w'               # w' >= 0, sum w' = 1, same balance

