function COLORFUL_1D(C[0..r-1]):
    require r >= 2 and each C[i] captures origin
    for i in 0..r-1:
        if 0 in C[i]:
            t[i] <- 0; t[j] <- any(C[j]) for j != i
            w[i] <- 1; w[j] <- 0 for j != i
            return (t, w)
    a <- any positive element of C[0]
    b <- any negative element of C[1]
    t[0] <- a; t[1] <- b; t[j] <- any(C[j]) for j >= 2
    w[0] <- -b; w[1] <- a; w[j] <- 0 for j >= 2
    return (t, w)          # (-b)a + a b = 0

