function PRUNE(V[1..n], w[1..n], d):
    support <- {i : w[i] > 0}
    while |support| > d + 1:
        u <- nonzero kernel vector of [ (V[i],1) : i in support ]
        if u = 0: break
        if no i in support has u[i] < 0: u <- -u
        theta <- min{ w[i]/(-u[i]) : i in support, u[i] < 0 }
        w <- w + theta * u
        zero out tiny w[i]
        support <- {i : w[i] > 0}
    return (support, w)
